lifecycle.insecure:
// authorised by the auto-sent cookie alone
app.post('/change-email', requireLogin, (req, res) => {
  db.setEmail(req.user.id, req.body.email);
});

lifecycle.secure:
// require an unpredictable token an attacker page can't read
app.post('/change-email', requireLogin, (req, res) => {
  if (req.get('x-csrf-token') !== session.csrfToken) return res.sendStatus(403);
  db.setEmail(req.user.id, req.body.email);
});
// plus: set cookies SameSite=Lax/Strict; keep GET side-effect-free.
